def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_c = 0
    recent_opp_d = 0
    recent_my_d = 0
    for i, (a, b) in enumerate(history):
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
        if i >= n - 8:
            if b == 'D':
                recent_opp_d += 1
            if a == 'D':
                recent_my_d += 1

    opp_d = n - opp_c
    opp_rate = opp_c / float(n)

    last_m, last_o = history[-1]

    if n <= 3:
        return 'C'

    if opp_d == 0:
        return 'C'

    if opp_rate < 0.15:
        if n > 15 and recent_opp_d >= 7:
            return 'D'
        if last_o == 'D' and rng.random() < 0.05:
            return 'C'
        return 'D'

    if opp_rate > 0.88 and recent_opp_d == 0:
        if last_o == 'C':
            if n >= 90 and rng.random() < 0.25:
                return 'D'
            return 'C'

    if last_o == 'C':
        if last_m == 'D':
            return 'C'
        if recent_opp_d >= 3:
            return 'C'
        return 'C'

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    if opp_d_streak >= 2:
        if (opp_rate > 0.6 and recent_opp_d <= 4 and n > 20 and rng.random() < 0.25):
            return 'C'
        if opp_d_streak >= 4 and opp_rate > 0.5 and rng.random() < 0.15:
            return 'C'
        return 'D'

    if opp_rate > 0.65 and n > 30:
        if recent_opp_d <= 2:
            return 'C'
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    if opp_rate > 0.45:
        if recent_opp_d <= 3 and rng.random() < 0.4:
            return 'C'
        return 'D'

    if rng.random() < 0.08:
        return 'C'
    return 'D'
